/* Design-only state machine. No fetch, uploads, device access, or persistent credentials. */
'use strict';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const navs=[['receive','接收','device'],['transfers','传输','transfer'],['storage','存储','drive'],['settings','设置','settings']];
const review=new URLSearchParams(location.search);
let route=catalog.some(x=>x.id===review.get('screen'))?review.get('screen'):'receive', scenario='', stack=[], tab='receive', filter='全部', message='', messageTimer;
const model={browser:true,restore:true,thermal:true,threshold:40,conversion:false,relay:true,paired:false,automatic:false,theme:'跟随系统',language:'简体中文',name:'Pixel XL',code:'',codeError:'',formError:'',deviceEnabled:true,busy:false,receivePaused:false,protection:null,experimentsSeen:false};
const info=id=>catalog.find(x=>x.id===id);
const discoveryDot=()=>model.experimentsSeen?'':'<span class="discovery-dot" role="img" aria-label="有新功能可了解"></span>';
const openButton=(text,id,style='')=>`<button class="button ${style}" data-open="${id}">${esc(text)}</button>`;
const act=(text,action,style='')=>`<button class="button ${style}" data-do="${action}" ${model.busy?'disabled':''}>${esc(text)}</button>`;
const link=(text,id)=>`<button class="link" data-open="${id}">${esc(text)}${icon('chevron')}</button>`;
const group=(title,rows)=>`<div class="group">${title?`<div class="group-title">${esc(title)}</div>`:''}${rows}</div>`;
const setting=(title,note='',target='',value='',ic='')=>`<${target?'button':'div'} class="setting" ${target?`data-open="${target}"`:''}><div class="grow"><strong>${esc(title)}${target==='experiments'?discoveryDot():''}</strong>${note?`<p>${esc(note)}</p>`:''}</div>${value?`<span class="value">${esc(value)}</span>`:target?icon('chevron'):''}</${target?'button':'div'}>`;
const switchRow=(title,note,key)=>`<div class="setting"><div class="grow"><strong>${esc(title)}</strong>${note?`<p>${esc(note)}</p>`:''}</div><button class="switch ${model[key]?'on':''}" role="switch" aria-label="${esc(title)}" aria-checked="${model[key]}" data-toggle="${key}" ${model.busy?'disabled':''}></button></div>`;
const note=(title,body='',kind='')=>`<div class="notice ${kind}">${icon(kind==='error'||kind==='warning'?'alert':'info')}<div class="grow"><strong>${esc(title)}</strong>${body?`<p>${esc(body)}</p>`:''}</div></div>`;
const pill=(text,kind='',ic='')=>`<span class="pill ${kind}">${ic?icon(ic):''}${esc(text)}</span>`;
const field=(label,key,value,type='text',error='')=>`<label class="field">${esc(label)}<input id="field-${key}" data-edit="${key}" type="${type}" ${key==='code'?'inputmode="numeric" maxlength="10" autocomplete="off"':''} value="${esc(value)}" class="${error?'invalid':''}" aria-invalid="${!!error}" ${error?`aria-describedby="error-${key}"`:''}>${error?`<span id="error-${key}" class="error" role="alert">${esc(error)}</span>`:''}</label>`;
const choices=(rows,key,current)=>group('',rows.map(([v,label])=>`<button class="setting" data-choice="${key}" data-value="${v}"><div class="grow"><strong>${esc(label)}</strong></div>${current===v?pill('已选','active','check'):''}</button>`).join(''));
const select=(label,key,values,current)=>`<label class="setting select-row">${icon(key.startsWith('log')?'clock':'drive')}<span class="grow"><strong>${esc(label)}</strong></span><select data-edit="${key}" aria-label="${esc(label)}">${values.map(v=>`<option ${String(v)===String(current)?'selected':''}>${v}</option>`).join('')}</select></label>`;
const failure=(text='未能保存，请重试。')=>note('操作未完成',text,'error')+act('重试','retry');
const busy=()=>note(model.busy?'正在保存…':'设置不会立即改变现有备份任务。');
const readings=(values)=>`<div class="readings">${values.map(([v,t])=>`<div>${esc(v)}<small>${esc(t)}</small></div>`).join('')}</div>`;
const files=Array.from({length:22},(_,i)=>({name:`IMG_${5442-i}.${i%4===2?'MOV':'HEIC'}`,type:i%4===2?'视频 · 00:18':i%3?'照片':'实况',time:`10/02 12:${59-i}`,state:i<2?'failed':i<5?'active':i<7?'waiting':'saved'}));
const states={failed:['相册处理失败','alert'],active:['接收中','transfer'],waiting:['已接收 · 待处理','clock'],saved:['已保存到相册','check']};
function fileRow(f){return `<button class="file" data-open="file-detail"><div class="thumb">${f.type.includes('视频')?icon('play'):''}</div><div class="grow"><strong>${f.name}</strong><p>${f.time} · ${f.type}</p></div>${pill(states[f.state][0],f.state,states[f.state][1])}</button>`}
function actions(...items){return items.join('')}
function content(id) {
 const failed=/失败|不可用|无法|无效|不兼容|账号改变|超时|中断/.test(scenario), running=/中|等待相册|等待降温/.test(scenario);
 switch(id) {
 case 'receive':{
  const empty=scenario==='首次使用',starting=scenario==='启动中',failedStart=scenario==='启动失败';
  const thermal=scenario==='高温暂停'||model.protection==='thermal',space=scenario==='空间不足'||model.protection==='space';
  const paused=model.receivePaused||scenario==='手动暂停';
  const heading=empty?'准备连接设备':starting?'正在启动接收':failedStart?'接收无法启动':paused?'新接收已暂停':thermal?'等待手机降温':space?'等待释放空间':scenario==='已保存'?'已保存到 Pixel 相册':scenario==='接收中'?'正在接收':'等待接收';
  const controls=empty||starting||failedStart?openButton('连接新设备','pairing','primary full'):`<div class="receive-actions">${paused?act('继续新接收','resume','primary')+openButton('连接新设备','pairing'):openButton('连接新设备','pairing','primary')+act('暂停新接收','pause')}</div>`;
  return `<div class="hero"><div class="row"><div class="art ${empty?'brand':''}">${empty?'<img src="../../assets/AppIcon.png" alt="">':icon('device')}</div><div class="grow"><h2>${heading}</h2><p>${model.name} · ${empty?'尚未开始接收':'同一 Wi‑Fi'}</p></div>${pill(empty?'未启动':starting?'启动中':paused||thermal||space||failedStart?'暂停':'在线',thermal||space||paused?'waiting':'')}</div>${controls}${paused?note('仅暂停新接收','已接收文件的相册处理继续。点继续后，仍按温度保护与空间条件决定能否接收。'):''}</div>${failedStart?note('接收无法启动','端口冲突或 Wi‑Fi 地址不可用时，请先检查具体原因。已有文件保留。','error')+link('查看连接帮助','help-connection'):thermal?note('温度保护仍生效','演示电池温度 43 °C；低于设置阈值 2 °C，且系统热保护解除后继续。','warning'):space?note('空间保护仍生效','达到原件上限或低于最低可用空间时暂停新接收；继续按钮不会绕过保护。','warning'):starting?note('正在启动接收服务…','就绪前不会显示为正在接收。'):''}<h3>设备状态</h3>${readings([[thermal?'43.0 °C':'37.2 °C','电池温度'],[space?'1.2 GB':'22.4 GB','可用空间'],['78%','电量 · 充电中']])}<div class="section-divider"></div>${empty?`<h3>怎么配对？</h3>${group('',setting('连接手机','显示 Pixel 配对码，让 iPhone / Android 发送端扫描','pair-code','','qr')+setting('连接电脑','用 Pixel 扫描 Mac / Windows 发送端配对码','pair-scan','','scan'))}${note('选择连接方式后，会自动启动接收服务。')}`:`<div class="row"><h3 class="grow">接收概况</h3>${link('全部记录','transfers')}</div>${readings([[scenario==='记录为空'?'0':'240','已保存'],[scenario==='记录为空'?'0':'6','进行中'],[scenario==='记录为空'?'0':'2','失败']])}<h3>最近记录</h3>${scenario==='记录为空'?note('暂无接收记录'):scenario==='记录读取失败'?failure('最近记录暂不可读，已有接收与保存结果未改变。'):files.slice(2,5).map(fileRow).join('')}`}`;
 }

 case 'system-notification':{const bodies={"接收已就绪": "可在已连接的设备上开始备份。", "正在启动接收": "正在准备连接。", "正在恢复连接": "将自动重试，已接收文件保留。", "接收尚未启动": "打开备份鸭继续接收。", "正在接收照片": "接收完成后将保存到手机相册。", "正在保存到手机相册": "正在处理已接收的文件。", "新传输已暂停": "已接收文件继续保存，打开备份鸭可继续接收。", "等待手机降温": "降温后将自动继续接收和保存。", "等待释放空间": "释放手机空间后将继续处理。", "部分文件需要处理": "打开传输记录查看原因并重试。"};return `<p>Android system notification · synthetic preview</p><div class="notification-reference"><header><img src="../../assets/BackupDuckMonochrome.svg" width="24" height="24" alt="">备份鸭</header><strong>${esc(scenario)}</strong><p>${esc(bodies[scenario])}</p></div><p>Native Android owns notification layout and tint. Verify the actual system surface.</p>`;}
 case 'pairing':return `<p>选择发送设备。接收服务会自动启动。</p>${scenario==='启动失败'?failure('Wi‑Fi 地址不可用，请检查网络。'):scenario==='启动中'?note('正在启动接收服务…','准备完成后显示配对步骤。'):group('',setting('连接手机','显示 Pixel 配对码，让手机扫描','pair-code','','qr')+setting('连接电脑','Pixel 扫描电脑发送端配对码','pair-scan','','scan'))}`;
 case 'pair-code':return scenario==='失败'?failure('暂时无法生成配对码。'):scenario==='接收不可用'?note('接收服务暂不可用','恢复接收后刷新配对码。','warning')+act('刷新配对码','pair-refresh','primary'): `<p>保持两台设备连接同一 Wi‑Fi，用 iPhone / Android 备份鸭发送端扫描。</p><div class="demo-qr"><strong>演示 · 无效码</strong></div><p>Pixel 配对码使用当前接收身份；接收地址改变后需刷新。电脑发送端邀请码的有效期由真实协议处理。</p>${act('刷新配对码','pair-refresh')}${act('模拟配对成功','pair-success','full primary')}`;
 case 'pair-scan':return `<div class="camera-demo" style="height:320px;max-width:240px;margin:0 auto 20px;aspect-ratio:3/4">${icon('scan')}</div><h3>扫描电脑发送端配对码</h3><p>使用竖屏取景框。在 Mac / Windows 发送端的“接收设备”页显示配对码，放入框内。</p>${scenario==='相机权限'?note('需要相机权限','仅用于扫描配对码。')+openButton('允许相机访问','system-permission','primary'):scenario==='无效码'?failure('该二维码不是有效的备份鸭配对码。'):scenario==='配对成功'?note('配对成功','返回接收页即可接收备份。')+openButton('返回接收','receive','primary'):act('模拟识别配对码','pair-success','primary')}`;
 case 'transfers':{const empty=scenario==='空白'||scenario==='筛选无匹配';const filtered=filter!=='全部'||scenario==='筛选无匹配';return `<div class="row"><p class="grow">${empty?'0':'248'} 个项目 · ${empty?'0':'240'} 个已保存</p>${link('状态说明','status-guide')}</div><div class="chips">${['全部','进行中','失败','已保存'].map(v=>`<button class="chip ${filter===v?'active':''}" data-filter="${v}">${v}</button>`).join('')}</div>${scenario==='加载中'?note('正在读取本机记录…','缩略图与列表位置保持稳定。'):empty?`<div class="empty"><h2>${filtered?'没有符合筛选条件的记录':'还没有传输记录'}</h2>${filtered?'':'<p>开始一次备份后，可查看传输与相册处理结果。</p>'}${filtered?act('清除筛选','clear-filters'):scenario==='空白'&&!model.paired?openButton('连接新设备','pairing','primary full'):''}</div>`:files.filter(f=>filter==='全部'||filter==='失败'&&f.state==='failed'||filter==='已保存'&&f.state==='saved'||filter==='进行中'&&['active','waiting'].includes(f.state)).map(fileRow).join('')}`;}
 case 'filters':return group('',setting('媒体类型','按照片、实况、视频或连拍筛选','filter-kind','全部')+setting('来源设备','按发送设备筛选','filter-sender','全部'))+act('刷新记录','refresh')+act('重试失败处理','retry-batch');
 case 'filter-kind':return choices(['全部','照片','实况','视频','连拍'].map(x=>[x,x]),'kind','全部');
 case 'filter-sender':return scenario==='空白'?note('还没有来源设备记录。'):choices(['全部','示例 iPhone','示例 Mac'].map(x=>[x,x]),'sender','全部');
 case 'status-guide':return group('',Object.entries(states).map(([s,[text,ic]])=>setting(text,{failed:'原件保留，可查看原因并重试。',active:'字节传输尚未完成。',waiting:'原件已校验，等待加入相册。',saved:'已加入 Pixel 系统相册。'}[s],'','',ic)).join(''))+note('这些状态不等于云端已备份','请在 Google 相册中确认云端结果。');
 case 'file-detail':{const video=scenario==='视频';const copyMissing=scenario==='副本缺失';let stage=scenario==='失败'?'failed':scenario==='接收中'?'active':scenario==='待处理'?'waiting':'saved';return `<div class="preview" style="background-image:url(../android-sender-v1.2/sample-photo-atlas.png);background-size:300% 400%;background-position:0 0">${video?icon('play'):""}</div><div class="row"><h2 class="grow">${video?'Generated_video.mp4':'IMG_5442.HEIC'}</h2>${pill(states[stage][0],stage)}</div><dl class="definitions">${[['类型',video?'视频 · 00:18（演示）':'实况'],['拍摄时间',scenario==='时间缺失'?'未提供':'2026/10/02 12:59'],['来源设备','示例 iPhone'],['大小','12.6 MB'],['原件',scenario==='原件已释放'?'已按保留策略释放':stage==='active'?'尚未接收完成':'保留在 Pixel，可重试处理']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><ul class="timeline"><li class="${stage==='active'?'pending':''}">${stage==='active'?'正在接收原件':'原件已接收并校验'}<p>${stage==='active'?'尚未完成':'10/02 13:03'}</p></li><li class="${stage==='saved'?'':'pending'}">${states[stage][0]}<p>${stage==='failed'?'输入结构需要兼容转换，原件未删除':stage==='saved'?'10/02 13:04':'保存尚未完成'}</p></li><li class="pending">Google 相册云端<p>备份鸭不能读取该状态，请在 Google 相册确认。</p></li></ul>${stage==='failed'?note('怎么处理？','先重试；仍失败时查看原因，再决定是否开启兼容转换。','error')+act('重试处理','retry-file','primary')+link('兼容转换说明','conversion'):''}${copyMissing?note('相册副本暂不可用','未找到可打开的本机副本；保存记录与云端状态独立。','warning'):stage==='saved'?openButton('查看相册副本','system-gallery'):''}`;}
 case 'storage':return `<h2>${scenario==='空间不足'?'空间不足，接收已暂停':'空间足够，备份安心。'}</h2><p>${model.name} · 本机存储</p>${scenario==='读取失败'?failure('本机空间统计未能读取。'): `<div class="space"><strong>可用空间</strong><div class="amount">${scenario==='空间不足'?'1.2':'22.4'} GB <small>/ 64 GB</small></div><div class="meter"><span style="width:65%"></span></div><p>● 备份鸭原件 11.5 GB</p><p>● 相册副本与未完成文件 5.1 GB</p><p>● 其他 25.0 GB</p></div>`}${group('文件保留',setting('原件处理方式','','retention',model.relay?'自动回收':'保留')+setting('空间限制','','storage-limits','16 GB')+setting('待处理文件','','transfers','2 个'))}${openButton('查看存储明细','storage-detail','full')}`;
 case 'storage-detail':return scenario==='读取失败'?failure('存储统计暂不可用。'):group('应用中转文件',setting('已接收的中转原件','','','11.5 GB')+setting('未接收完成','','','328 MB'))+group('系统相册副本',setting('已保存的相册副本','240 个项目','','4.8 GB')+setting('未完成的相册副本','6 个项目','','128 MB'));
 case 'storage-limits':return `<p>达到上限或低于预留空间时，暂停新接收，不自动删除原件。</p>${select('原件空间上限','budget',['2 GB','4 GB','6 GB','10 GB','16 GB','32 GB','64 GB','128 GB'],'16 GB')}${select('最低可用空间','reserve',['0 GB','1 GB','2 GB','3 GB','5 GB','10 GB'],'3 GB')}${scenario==='保存失败'?failure():busy()}`;
 case 'retention':return retentionContent();
 case 'relay-scope':return retentionContent(true);
 case 'relay-history':return historicalCheckContent();
 case 'relay-preview':return historicalCheckContent('preview');
 case 'relay-reclaim':return historicalCheckContent('reclaim');
 case 'relay-result':return historicalCheckContent('result');
 case 'archive':return `<p>将应用内中转原件与清单导出为 ZIP，完成后重新读取并校验。选择目标位置后开始。</p>${note('导出不会删除原件','校验通过后，再单独选择是否回收。')}`;
 case 'archive-progress':return failed?failure('导出未完成，应用内原件保留。'):scenario==='没有原件'?note('没有可导出的原件。'):scenario==='已取消'?note('导出已取消','目标位置可能留下未完成文件，应用内原件保留。'):note(scenario==='校验中'?'正在校验导出文件…':'正在导出原件…','请保持目标存储位置可访问。')+openButton('查看模拟校验结果','archive-result','primary full')+act('取消导出','cancel-job');
 case 'archive-result':return scenario==='校验失败'?failure('导出文件不完整，原件未回收。'):note('导出已通过校验','128 项原件已导出。')+openButton('保留应用内原件','storage','full')+openButton('回收已导出原件','archive-reclaim','full');
 case 'archive-reclaim':return `<p>再次校验 ZIP 后，回收这 128 项应用内原件。Pixel 相册照片与接收记录保留。</p>${failed?failure('导出文件校验失败，原件继续保留。'):running?note('正在校验并回收…'):note('请确认导出文件保存位置可靠。','','warning')}`;
 case 'settings':return `${group('接收设置',switchRow('重启后自动接收','','restore')+setting('温度保护','','thermal',model.thermal?model.threshold+' °C':'关闭')+setting('兼容转换','','conversion',model.conversion?'开启':'关闭')+setting('停止接收服务','','stop-receiving'))}${group('',setting('浏览器管理','','browser',model.browser?'开启':'关闭'))}${group('设备与外观',setting('设备名称','','device-name',model.name)+setting('发送设备','','devices')+setting('外观','','appearance',model.theme)+setting('语言','','language',model.language))}${group('记录与导出',setting('日志保留','','log-limits')+setting('导出日志','','export-report')+setting('导出相册保存记录','','gallery-record-export')+setting('导出原件归档','','archive'))}${group('实验功能',setting('实验功能','','experiments'))}${group('应用与帮助',setting('应用更新','','updates','0.3.0')+setting('使用帮助','','help')+'')}`;
 case 'thermal':return `<p>使用 Pixel 电池传感器读数。温度低于暂停阈值 2 °C，且系统热保护解除后继续。</p>${group('',switchRow('温度保护','关闭后不按此温度阈值暂停。','thermal'))}${choices(Array.from({length:11},(_,i)=>[String(i+35),(i+35)+' °C'+(i+35===40?'（默认）':'')]),'threshold',String(model.threshold))}${failed?failure():''}`;
 case 'conversion':return group('',switchRow('允许兼容转换','仅在直接封装明确不支持输入结构时转换。','conversion'))+note('优先保留原图、视频和音频','关闭时，需要转换的文件会处理失败并保留原件，可稍后重试。')+note('云端“正在准备”不会触发转换。');
 case 'browser':return `<p>在可信任的同一 Wi‑Fi 上，用电脑管理这台 Pixel。</p>${group('',switchRow('允许浏览器管理','关闭后浏览器无法访问，不影响设备配对。','browser')+setting('访问管理页','','browser-access')+setting('设置访问码','','browser-code')+setting('退出所有浏览器','','browser-revoke'))}${scenario==='启动中'?note('正在开启浏览器管理…'):scenario==='启动失败'?failure('接收服务暂不可用，先检查连接。'):note('仅在可信任的局域网使用','当前管理服务使用 HTTP。')}${scenario==='接收未启动'?note('请先开启接收，并启用浏览器管理。')+act('开始接收','browser-ready','primary full'):''}`;
 case 'browser-access':return scenario==='接收未启动'?note('接收服务尚未启动','启动后才能获得可访问的管理地址。','warning')+act('启动接收服务','browser-start','primary'):scenario==='地址不可用'?failure('Wi‑Fi 地址暂不可用，请检查网络后重试。'): `<p>在电脑浏览器输入地址，再使用访问码登录。</p>${group('',setting('管理地址','http://192.0.2.10:8485（演示）')+setting('访问码','0000000000（演示，无效）'))}${act('复制管理地址','copy-address','primary full')}${note('不要向不信任的人分享访问码','访问码和浏览器登录，与发送设备配对独立。')}`;
 case 'browser-code':return `<p>访问码在重启和升级后保持不变。保存后所有浏览器需要重新登录，不影响发送设备配对。</p>${field('新的 10 位数字访问码','code',model.code,'password',model.codeError|| (scenario==='输入错误'?'请输入 10 位数字。':''))}${model.formError||scenario==='保存失败'?failure('保存未完成，原访问码仍有效。'):busy()}${openButton('重置为随机访问码','browser-reset','full')}`;
 case 'browser-reset':return `<p>生成新的随机访问码，并让所有浏览器退出登录？新码可在“访问管理页”查看。</p>${model.formError||failed?failure('重置未完成，原访问码仍有效。'):running||model.busy?note('正在重置…'):note('不会改变设备配对和备份任务。')}`;
 case 'browser-revoke':return `<p>撤销所有浏览器的登录？访问码、发送设备配对和备份任务保持不变。</p>${model.formError||failed?failure('撤销未完成，请重试。'):running||model.busy?note('正在撤销登录…'):note('下次访问需要重新输入访问码。')}`;
 case 'device-name':return `${field('设备名称','nameDraft',model.nameDraft??model.name,'text',scenario==='名称无效'?'名称需为 1–40 个 Unicode 码点，且不能包含控制字符。':'')}${failed?failure():running?note('正在保存…'):''}`;
 case 'devices':return scenario==='空白'?note('还没有发送设备','配对后会显示在这里。')+openButton('连接新设备','pairing','primary full'):failed?failure('设备记录未能读取。'):group('',setting('示例 iPhone','iPhone · 最近连接 10/02 13:04','device-detail','允许接收','device')+setting('示例 Mac','Mac · 最近连接 10/01 18:00','device-detail','允许接收','laptop'));
 case 'device-detail':return group('',setting('设备名称','示例 iPhone')+setting('设备类型','iPhone')+setting('最近地址','192.0.2.20（演示）')+setting('最近连接','10/02 13:04'))+note('禁用后不接受此发送端的新请求','不删除接收记录或照片。')+openButton(scenario==='已禁用'?'允许接收':'禁用此设备','device-confirm','full');
 case 'device-confirm':return `<p>更改此发送设备的接收权限？接收记录和已保存文件不会删除。</p>${failed?failure():running?note('正在保存…'):''}`;
 case 'appearance':return choices(['跟随系统','浅色','深色'].map(x=>[x,x]),'theme',model.theme);
 case 'language':return choices(['跟随系统','简体中文','English'].map(x=>[x,x]),'language',model.language);
 case 'help':return `<p>只阅读说明，不会在帮助里进入配对、设置或导出流程。需要操作时，请按说明里的路径返回对应页面。</p>${group('',setting('连接与配对','同一网络、配对方向与接收地址','help-connection')+setting('后台接收','锁屏、后台限制与重启恢复','help-background')+setting('接收与保存','原件、Pixel 相册与云端是不同阶段','help-results')+setting('空间与原件','保留、回收和导出','help-storage')+setting('失败恢复','重试、诊断与更新','help-recovery'))}`;
 case 'help-connection':return note('当前接收地址',scenario==='未启动'?'开始接收后可查看当前地址。':failed?'暂时无法读取当前地址；查看诊断可排查原因。':'192.0.2.10:8484（演示）')+group('',setting('同一 Wi‑Fi','两台设备需处于可互通的局域网，接收端需有 IPv4 地址。访客网络、客户端隔离及 VPN 可能阻止连接；VPN 应允许局域网。')+setting('配对方向','手机发送端（iPhone / Android）扫 Pixel 的码；Pixel 扫电脑发送端（Mac / Windows）的码。选择连接方式后会自动启动接收。操作路径：接收 → 连接新设备。')+setting('启动失败','端口冲突或 Wi‑Fi 地址不可用时，按具体原因恢复。不需要清除配对或已有文件。')+setting('接收地址变化','新版发送端会在局域网发现新地址，并用已有配对验证；手动暂停仍保持暂停。如果发现被网络阻断，可按接收页的连接方式重新配对。'));
 case 'help-background':return group('',setting('后台持续接收','接收运行时使用系统前台服务和通知。系统省电、后台限制或服务运行时限仍可能中断任务；已有接收记录与未完成文件保留。')+setting('自动恢复','操作路径：设置 → 接收设置 → 重启后自动接收。Android 15 或更高版本需要点按通知或打开应用恢复，不能保证开机直接开始接收。主动停止服务后不会自动恢复。')+setting('发送端限制','iPhone 的后台准备和传输受系统调度限制，不能保证锁屏后持续备份；大量导入宜保持前台。Mac 发送端需要应用运行且电脑保持唤醒。'));
 case 'help-results':return group('',setting('已接收','项目全部资源已持久保存并通过完整性校验；只说明原件到达 Pixel。')+setting('已保存到相册','已加入 Pixel 系统相册。受支持实况与连拍的展示仍需由外部相册识别。')+setting('Google 相册云端','云端由 Google 相册上传，备份鸭不能证明云端成功。请在 Google 相册选择正确账号，并按需要开启备份鸭设备文件夹的备份；打开相册不等于上传完成。'));
 case 'help-storage':return group('',setting('空间限制','原件上限与最低可用空间共同限制新接收；相册副本和临时文件也占空间。操作路径：存储 → 空间限制。')+setting('保留原件','相册处理失败时可从原件重试。操作路径：存储 → 保留原件。Google 相册释放空间不会清理备份鸭私有原件。')+setting('自动回收','验证系统相册副本后回收中转原件，不验证云端。副本缺失、变化或无法校验时继续保留。关闭不会恢复已回收原件。操作路径：存储 → 保留原件。')+setting('导出原件','ZIP 导出通过回读校验后，才能另行选择回收；导出在本机仍占空间。操作路径：存储 → 存储明细 → 导出原件。'));
 case 'help-recovery':return group('',setting('重试相册处理','先查看失败原因。原件已接收而相册处理失败时无需重新上传；重试请求不代表立即成功。操作路径：传输 → 失败 → 文件详情 → 重试处理。')+setting('导出诊断','反馈时附发生时间、设备状态与前后台情况。报告不含照片内容或配对凭据，但可能包含任务标识，分享前请检查。操作路径：设置 → 诊断与实验 → 导出诊断日志。')+setting('应用更新','操作路径：设置 → 应用更新。签名不兼容时不要直接卸载或清除存储，以免丢失私有原件和记录。'));

 case 'updates':return group('',setting('当前版本','0.3.0（演示）')+switchRow('自动检查更新','每天最多自动检查一次。','automatic'))+note({检查中:'正在检查更新…',最新版:'已是最新版',可更新:'可更新至 0.2.0-rc.4',检查失败:'检查失败，请检查网络后重试。',下载中:'正在下载更新…',下载失败:'下载未完成，请重试。',安装权限:'请允许此应用安装更新。',签名不兼容:'安装包签名与现有应用不同。',开发版本:'当前是验证版本，无法直接安装正式包。'}[scenario],scenario==='签名不兼容'?'不要卸载或清除存储，先保留原件和记录。':'',failed?'error':'')+actions(act(scenario==='可更新'?'下载更新':'检查更新','update-check','primary full'),scenario==='安装权限'?openButton('打开安装权限','system-install','full'):'',link('官方网站','system-website'));
 case 'diagnostics':return group('',setting('日志保留','','log-limits')+setting('导出诊断日志','','export-report'));
 case 'log-limits':return `<p>只管理运行日志，不删除照片、接收记录或配对。</p>${select('日志保留天数','logDays',['1 天','7 天','14 天','30 天','90 天'],'14 天')}${select('最大日志条目','logLimit',['1000','5000','10000','20000'],'10000')}${failed?failure():busy()}`;
 case 'gallery-record-export':return note('相册保存记录','保存文件名、字节大小、校验及保存时间。用于本机核对或其他工具；不含照片内容，不代表云端已上传。')+(scenario==='导出失败'?failure('保存记录未能写入所选位置。'):scenario==='导出中'?note('正在导出保存记录…'):scenario==='导出成功'?note('保存记录已导出'):openButton('选择保存位置','system-document','primary full'));
 case 'photos-report-export':return note('Google 相册页面检查报告','只包含页面观察阶段及应用版本；页面观察不等于逐张云端备份确认。')+(scenario==='导出失败'?failure('检查报告未能写入所选位置。'):scenario==='导出中'?note('正在导出检查报告…'):scenario==='导出成功'?note('检查报告已导出'):openButton('选择保存位置','system-document','primary full'));
 case 'export-report':return note('诊断日志','阶段、任务标识与字节数等运行事件；不含照片或配对凭据。')+(scenario==='导出失败'?failure('日志未能写入所选位置。'):scenario==='导出中'?note('正在导出日志…'):scenario==='导出成功'?note('日志已导出','分享前可先查看内容。'):openButton('选择保存位置','system-document','primary full'));
 case 'experiments':return `<p>接收设备空间不足时，让 Google 相册释放已备份的设备副本。需要一次设置，默认关闭。</p>${group('',setting('自动释放空间','保留云端照片，释放手机空间。','cleanup'))}<p>实验功能可能受 Google 相册版本影响。</p>`;
 case 'cleanup':return `<p>通过 Google 相册的“释放空间”，移除它已确认备份的设备副本，保留云端照片。可能包括其他应用的已备份照片。</p>`+group('首次设置',setting('1. 允许操作 Google 相册',scenario==='未授权'?'未开启 · 点击前往系统设置，开启本应用的无障碍服务。':'已开启','cleanup-disclosure')+setting('2. 确认相册账号',scenario==='未授权'||scenario==='未绑定'?'未确认 · 使用这台手机 Google 相册中当前登录的账号。':scenario==='结果待核对'?'账号已确认 · 点击继续检查上次清理结果。':'已确认 · 更换账号后需要重新确认。',scenario==='结果待核对'?'cleanup-progress':'cleanup-bind'))+group('自动释放',switchRow('空间不足时自动释放','先完成上面的设置。运行时暂停新增传输；有密码锁屏时需手动解锁。','automatic'))+(scenario==='就绪'||scenario==='未授权'||scenario==='未绑定'?'':note({运行中:'正在检查释放空间',结果待核对:'等待 Google 相册结果',账号改变:'相册账号已改变，请重新确认'}[scenario],scenario==='结果待核对'?'检查会重新进入结果页面；如果 Google 相册再次提供释放按钮，请手动核对后回到这里，不重复释放。':'',scenario==='账号改变'?'error':''))+(scenario==='未授权'||scenario==='未绑定'?'':openButton(scenario==='结果待核对'?'检查清理结果':'立即释放空间','cleanup-progress','primary full'))+(scenario==='运行中'?act('停止检查','cancel-job','full'):'')+(scenario==='结果待核对'?openButton('已核对，恢复传输','cleanup-review','full'):'')+`<h3>遇到问题？</h3><p>无法打开或识别 Google 相册时，可检查页面并导出报告。正常使用无需执行。</p>`+openButton('检查 Google 相册页面','photos-diagnostics','check-page-action');
 case 'cleanup-disclosure':return `<p>仅在 Google 相册官方确认内容已安全备份时操作“释放空间”。可能影响此设备其他应用的已备份照片。</p><p>不点击删除，不清空云端回收站。本机只保存账号指纹；不保存或发送账号原文、截图、照片标签。</p><p>默认关闭，每轮最多 5 分钟；需要手机解锁。可随时停止或关闭系统无障碍服务，结果不明时不重复释放。</p>`;
 case 'cleanup-bind':return note(scenario==='已绑定'?'账号已绑定':scenario==='需要解锁'?'请先解锁手机':scenario==='无法识别'?'无法识别账号，已停止':'正在核对当前 Google 相册账号',scenario==='无法识别'?'请打开 Google 相册首页后重试。':'确认当前登录的账号，之后只为这个账号释放空间。',failed?'error':'')+openButton('打开 Google 相册','system-gallery','full')+act('模拟绑定成功','bind-success','full primary');
 case 'cleanup-progress':return note({运行中:'正在核对账号与释放空间入口…',等待相册:'等待 Google 相册完成',已完成:'Google 相册已报告释放完成',没有可释放文件:'Google 相册没有可释放设备文件',页面无法识别:'无法识别页面，已停止点击',需要解锁:'请解锁手机后继续',超时:'本轮检查已超时',已停止:'检查已停止'}[scenario],scenario==='等待相册'?'新接收暂时暂停，不重复点击释放。':'',failed?'error':'')+act('停止检查','cancel-job')+openButton('已手动核对','cleanup-review','full');
 case 'cleanup-review':return `<p>请先在 Google 相册核对结果。确认后只恢复备份鸭传输，不删除文件，也不证明云端备份完成。自动清理会等待 15 分钟再尝试。</p>`;
 case 'photos-diagnostics':return note({未授权:'尚未开启无障碍服务',就绪:'准备开始页面检查',检查中:'正在观察 Google 相册页面',已完成:'页面检查已结束',超时:'检查已超时',中断:'检查已中断'}[scenario], '',failed?'error':'')+`<p>只用于排查页面识别问题，不释放空间。</p><p>开启权限后开始检查。在 Google 相册中打开头像菜单，再进入“释放此设备的空间”，不要点击最后的释放按钮。回到这里查看或导出结果。</p>`+group('',setting('Google 相册版本','演示版本')+setting('已观察阶段',scenario==='已完成'?'账号入口、确认、释放完成':'尚无完整观察记录'))+openButton('开启权限 / 查看授权','probe-disclosure','full')+act('开始检查','probe-start','full primary')+act('停止检查','cancel-job')+openButton('导出检查报告','photos-report-export','full');
 case 'probe-disclosure':return `<p>使用无障碍服务观察 Google 相册官方页面，不读取照片内容，不保存账号、屏幕截图或照片标签。</p><p>请按引导自行操作 Google 相册；检查仅用于排查页面识别问题。</p>`;
 case 'stop-receiving':return `<p>停止局域网接收服务？新的发送请求和浏览器管理将无法连接。已接收原件与备份记录保留，已接收文件的相册处理继续按既有任务运行。</p>`;
 case 'system-website':case 'system-permission':case 'system-document':case 'system-install':case 'system-accessibility':case 'system-gallery':{const data={ 'system-website':['外部浏览器','打开备份鸭官方网站。浏览器返回不改变更新、接收或配对状态。','updates'],'system-permission':['Android 系统权限','系统显示通知 / 相机权限。允许后回到请求流程，拒绝后保留解释和再次进入入口。','pair-scan'],'system-document':['Android 文件选择器','选择 ZIP 或报告保存位置。取消返回原页面，未开始导出；写入失败保留原件。','archive-progress'],'system-install':['Android 安装 / 外部网站','系统安装权限与安装确认由 Android 提供。取消后保留已下载文件；签名不兼容不提示卸载。','updates'],'system-accessibility':['Android 无障碍设置','Android 显示系统服务授权。返回后重新检查权限，未授权时不开启实验操作。','cleanup'],'system-gallery':['Google 相册','外部应用自行显示照片与云端结果。返回后不把打开相册当作云端成功。','receive']}[id];return `<div class="system-boundary"><h2>${data[0]}</h2><p>${data[1]}</p><p>系统 / 外部应用边界，无自定义仿制界面。</p></div>${scenario==='失败'||scenario==='未安装'?note('无法打开','返回应用后显示原因和重试入口。','error'):''}${act('模拟返回应用','system-return','primary full')}${act('取消 / 返回','back','full')}`;}
 case 'components':return `<div class="component-samples"><h3>图标与导航</h3><p>24 × 24 坐标，统一 1.7 描边；视觉 22dp、命中 48dp。</p><div class="row">${['info','device','transfer','drive','settings','more'].map(n=>`<button class="icon-btn" aria-label="${n}">${icon(n)}</button>`).join('')}</div><h3>按钮</h3>${act('主要操作','example','primary full')}${act('次要操作','example','full')}<h3>设置行</h3>${group('',setting('设置名称','辅助说明，与控制分开','appearance','跟随系统')+switchRow('开启功能','保存失败时恢复原值。','thermal'))}<h3>状态</h3><div class="chips">${Object.entries(states).map(([k,[t,ic]])=>pill(t,k,ic)).join('')}</div><h3>反馈</h3>${note('说明','无需操作的信息。')}${note('需要注意','附下一步入口。','warning')}${note('操作未完成','重要失败保留在当前页面。','error')}${act('展示短提示','example')}<h3>弹层与确认</h3>${openButton('输入表单','browser-code','full')}${openButton('确认操作','browser-revoke','full')}${openButton('长任务','relay-history','full')}</div>`;
 default:throw Error('Missing screen contract: '+id);
 }
}
function retentionContent(forceEdit=false){const editing=forceEdit||model.relayEditing;return `<p>中转原件是备份鸭在应用内保留的接收文件，与 Pixel 系统相册副本独立。</p>${group('',switchRow('自动回收中转原件','','relay'))}<p>自动回收先核对系统相册副本，再释放符合条件的中转原件。未保存、校验失败或正在使用的文件会保留；系统相册副本不会删除，云端备份需另行确认。</p>${editing?`<p>选择本次设置影响的接收记录，保存后生效。</p>${choices([['new','仅回收新原件'],['history','同时回收历史']],'relayDraft',model.relayDraft||'new')}${model.relayDraft==='history'?'<p>保存后也会核对已有接收原件，符合条件的会自动回收。</p>':''}${scenario.includes('失败')||model.formError?failure('保存未完成，原设置仍有效；本次选择保留。'):''}`:model.relay?act('调整自动回收范围','relay-edit','full'):''}${openButton('检查历史原件','relay-history','full')}`}
function historicalCheckContent(forceStage){const stage=forceStage||model.relayCheckStage||'scan';if(stage==='preview')return `<h2>${scenario==='无可回收项'?'没有可回收的中转原件':'可回收 120 项 · 1.8 GB（演示）'}</h2>${group('',setting('继续保留','4 项缺少校验记录')+setting('相册副本已变化','2 项')+setting('相册副本缺失','2 项'))}<p>只回收重新校验通过的中转原件，保留系统相册副本和接收记录；本次检查不会开启自动回收，也不确认云端备份。</p>`;if(stage==='reclaim')return note('正在回收已验证原件…','剩余项目仍逐项重新校验。');if(stage==='cancelled')return note('已停止后续回收','已处理的结果保留，剩余原件未继续回收。');if(stage==='result')return note('历史原件检查已完成','演示：已回收 120 项；不符合条件的继续保留。');if(scenario.includes('失败'))return failure('检查未完成，原件保留。')+act('重试检查','history-scan','full');return note(scenario==='等待降温'?'等待手机降温':'正在检查历史原件','这里只核对相册副本，尚未回收原件。')+act('模拟检查完成','history-preview','full')}
function footer(id){switch(id){case 'retention':case 'relay-scope':return model.relayEditing||id==='relay-scope'?actions(act('取消','relay-cancel'),act(model.busy?'保存中…':'保存','relay-save','primary')):'';case 'relay-history':case 'relay-preview':case 'relay-result':if(model.relayCheckStage==='reclaim')return '<button class="button" data-do="history-stop">停止后续回收</button>';return actions(act(model.relayCheckStage==='scan'&&id==='relay-history'?'取消检查':'完成','back'),(model.relayCheckStage==='preview'||id==='relay-preview')&&scenario!=='无可回收项'?act('回收已验证原件','history-reclaim','primary'):'');case 'browser-code':return act(model.busy?'保存中…':'保存访问码','save-code','primary');case 'browser-reset':return actions(act('取消','back'),act(model.busy?'重置中…':'重置访问码','reset-code','primary'));case 'browser-revoke':return actions(act('取消','back'),act(model.busy?'处理中…':'退出所有浏览器','revoke','danger'));case 'device-name':case 'storage-limits':case 'log-limits':return actions(act('取消','back'),act(model.busy?'保存中…':'保存','save','primary'));case 'device-confirm':return actions(act('取消','back'),act('确认更改','device-change','primary'));case 'relay-reclaim':return actions(act('取消','back'),openButton('开始模拟回收','relay-result','danger'));case 'archive':return actions(act('取消','back'),openButton('选择导出位置','system-document','primary'));case 'archive-reclaim':return actions(act('保留原件','back'),act('模拟回收完成','archive-done','danger'));case 'cleanup-disclosure':case 'probe-disclosure':return actions(act('取消','back'),openButton('同意并打开系统设置','system-accessibility','primary'));case 'cleanup-review':return actions(act('取消','back'),act('确认已核对','cleanup-reviewed','primary'));case 'stop-receiving':return actions(act('取消','back'),act('停止服务','stop','danger'));default:return '';}}
function navigate(id){if(!info(id))throw Error('Unknown design destination: '+id);stack.push({route,scenario,tab});route=id;if(id==='experiments')model.experimentsSeen=true;scenario=info(id).states[0];if(id==='device-name')model.nameDraft=model.name;model.codeError='';model.formError='';model.busy=false;if(navs.some(x=>x[0]===id))tab=id;render()}
function back(){const prev=stack.pop();if(prev){({route,scenario,tab}=prev)}else{route=tab;scenario=info(route).states[0]}model.busy=false;model.formError='';render()}
function frame(id){const main=navs.some(x=>x[0]===id);return `<div class="toolbar">${main?'':`<button class="icon-btn" data-do="back" aria-label="返回">${icon('back')}</button>`}<h1>${esc(info(id).title)}</h1>${id==='transfers'?`<button class="icon-btn" data-open="filters" aria-label="筛选与更多">${icon('more')}</button>`:''}</div><div class="content" data-screen="${id}">${content(id)}</div>${main?`<nav class="nav" aria-label="应用导航">${navs.map(([id,t,ic])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><span class="symbol">${icon(ic)}${id==='settings'?discoveryDot():''}</span><label>${t}</label></button>`).join('')}</nav>`:''}`;}
function render(){const spec=info(route);if(!scenario)scenario=spec.states[0];$('#scenario').innerHTML=spec.states.map(x=>`<option ${x===scenario?'selected':''}>${esc(x)}</option>`).join('');let markup;if(['sheet','confirm'].includes(spec.kind)){const under=stack.slice().reverse().find(x=>['page','review','system'].includes(info(x.route).kind))?.route||'settings';const originalScenario=scenario;scenario=info(under).states[0];markup=frame(under);scenario=originalScenario;const confirm=spec.kind==='confirm';markup+=`<div class="${confirm?'confirm-mask':'sheet-mask'}" data-dismiss="true"><section class="${confirm?'confirm':'sheet'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${confirm?`<h2 id="dialog-title">${spec.title}</h2>`:`<div class="handle"></div><div class="sheet-head"><h2 id="dialog-title">${spec.title}</h2><button class="icon-btn" data-do="back" aria-label="关闭">${icon('close')}</button></div>`}<div class="content" data-screen="${route}">${content(route)}</div>${footer(route)?`<div class="sheet-foot">${footer(route)}</div>`:''}</section></div>`}else markup=frame(route);$('#app').innerHTML=markup+(message?`<div class="snackbar" role="status">${esc(message)}<button class="link" data-do="dismiss-message">关闭</button></div>`:'');if(['sheet','confirm'].includes(spec.kind)){[...$('#app').children].filter(x=>!x.matches('.sheet-mask,.confirm-mask,.snackbar')).forEach(x=>x.inert=true)}$('#catalog').innerHTML=catalog.filter(x=>x.title.includes($('#search').value)).map(x=>`<button data-open="${x.id}" class="${route===x.id?'selected':''}">${x.title}<small>${x.id} · ${x.kind}</small></button>`).join('');$('#contract').innerHTML=`<div class="contract"><strong>${spec.id} · ${spec.title}</strong><p>来源：${spec.source} / ${spec.symbol}<br>呈现：${spec.kind} · 原生进度：${spec.native}<br>模拟状态：${spec.states.join(' / ')}</p><p>原型反馈不代表真实处理或云端上传结果。</p></div>`;document.documentElement.dataset.screen=route;}
function toast(text){message=text;render();clearTimeout(messageTimer);messageTimer=setTimeout(()=>{message='';render()},3500)}
function save(kind){const id=route;const fail=scenario.includes('失败');if(id==='device-name'&&(!model.nameDraft?.trim()||[...model.nameDraft.trim()].length>40||/[\u0000-\u001f\u007f\u2028-\u202e\u2066-\u2069]/.test(model.nameDraft))){scenario='名称无效';render();return}if(kind==='save-code'&&!/^[0-9]{10}$/.test(model.code)){model.codeError='请输入 10 位数字。';render();$('#field-code')?.focus();return}model.busy=true;model.formError='';render();setTimeout(()=>{if(route!==id)return;model.busy=false;if(fail){model.formError='保存未完成，原设置仍有效。';render()}else{if(kind==='save-code')model.code='';if(id==='device-name')model.name=model.nameDraft.trim();if(kind==='save'&&id==='relay-scope')model.relay=true;back();toast(kind==='revoke'?'已退出所有浏览器。':kind==='reset-code'?'访问码已重置，浏览器需重新登录。':'已保存。')}},700)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.disabled){if(model.busy&&b.dataset.do!=='history-stop')return;if(b.dataset.open){if(b.dataset.open==='relay-history')model.relayCheckStage='scan';navigate(b.dataset.open);return}if(b.dataset.tab){stack=[];route=tab=b.dataset.tab;scenario=info(route).states[0];render();return}if(b.dataset.toggle){const key=b.dataset.toggle;if(key==='relay'&&!model.relay){model.relayEditing=true;model.relayDraft='new';render();return}if(key==='automatic'&&route==='cleanup'&&!model.automatic){navigate('cleanup-disclosure');return}model[key]=!model[key];render();return}if(b.dataset.choice){const key=b.dataset.choice;model[key]=key==='threshold'?Number(b.dataset.value):b.dataset.value;if(key==='theme'&&model.theme!=='跟随系统')document.documentElement.dataset.theme=model.theme==='深色'?'dark':'light';if(!['relayScope','relayDraft','threshold'].includes(key))back();else render();return}const a=b.dataset.do;switch(a){case 'relay-edit':model.relayEditing=true;model.relayDraft='new';render();break;case 'relay-cancel':model.relayEditing=false;model.formError='';if(route==='relay-scope')back();else render();break;case 'relay-save':{const failed=scenario.includes('失败');model.busy=true;render();setTimeout(()=>{model.busy=false;if(failed){model.formError='保存失败';render()}else{model.relay=true;model.relayEditing=false;render();toast('设置已保存。')}},500);break}case 'history-preview':model.relayCheckStage='preview';render();break;case 'history-scan':model.relayCheckStage='scan';render();break;case 'history-stop':model.busy=false;model.relayCheckStage='cancelled';render();break;case 'history-reclaim':model.relayCheckStage='reclaim';model.busy=true;render();setTimeout(()=>{if(model.relayCheckStage!=='reclaim')return;model.busy=false;model.relayCheckStage='result';render()},600);break;case 'back':if(route==='retention'&&model.relayEditing){model.relayEditing=false;render()}else back();break;case 'system-return':{const origin=stack.at(-1)?.route;if(route==='system-document'){back();if(origin==='archive')navigate('archive-progress');else{scenario='导出中';render()}}else if(route==='system-accessibility'){back();navigate(origin==='probe-disclosure'?'photos-diagnostics':'cleanup')}else back();break;}case 'copy-address':toast('管理地址已复制（演示）。');break;case 'save-code':case 'save':case 'reset-code':case 'revoke':save(a);break;case 'retry':model.formError='';scenario=info(route).states[0];render();break;case 'clear-filters':filter='全部';scenario='正常';render();break;case 'pair-success':model.paired=true;stack=[];route=tab='receive';scenario='等待接收';model.receivePaused=false;render();toast('配对成功（演示）。');break;case 'pair-refresh':scenario='有效';render();break;case 'pause':model.receivePaused=true;scenario='手动暂停';render();break;case 'resume':model.receivePaused=false;scenario=model.protection==='thermal'?'高温暂停':model.protection==='space'?'空间不足':'等待接收';render();break;case 'retry-file':toast('已请求重试，成功前仍保留失败状态。');break;case 'retry-batch':toast('已请求重试失败处理。');break;case 'refresh':toast('记录已刷新，筛选与滚动位置保留（演示）。');break;case 'browser-start':model.browser=true;scenario='可访问';render();break;case 'browser-ready':model.browser=true;scenario='已开启';render();break;case 'device-change':model.deviceEnabled=!model.deviceEnabled;back();toast('接收权限已保存（演示）。');break;case 'bind-success':route='cleanup';scenario='就绪';render();break;case 'probe-start':scenario='检查中';render();break;case 'cleanup-reviewed':back();scenario='就绪';render();toast('已按手动核对结束等待。');break;case 'archive-done':back();toast('已回收导出校验通过的中转原件（演示）。');break;case 'stop':stack=[];route=tab='receive';scenario='首次使用';model.receivePaused=false;model.protection=null;render();break;case 'cancel-job':scenario=info(route).states.find(x=>x.includes('取消')||x.includes('停止'))||info(route).states[0];render();toast('后续任务已取消，已有文件保留。');break;case 'update-check':scenario=scenario==='可更新'?'下载中':'检查中';render();break;case 'example':toast('短提示：请求已提交。');break;case 'dismiss-message':message='';render();break;default:if(b.dataset.filter){filter=b.dataset.filter;render()}}}if(e.target.dataset.dismiss==='true'&&!model.busy)back()});
document.addEventListener('input',e=>{if(e.target.dataset.edit)model[e.target.dataset.edit]=e.target.value;if(e.target.id==='search')render()});
function applyScenario(){if(route==='receive'){model.receivePaused=scenario==='手动暂停';model.protection=scenario==='高温暂停'?'thermal':scenario==='空间不足'?'space':null;}if(route==='browser')model.browser=scenario!=='未开启';if(route==='thermal')model.thermal=scenario!=='保护关闭'}
$('#theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme').textContent=dark?'切换浅色':'切换深色'};$('#width').onchange=e=>{$('#phone').style.width=e.target.value+'px';$('#phone').style.height=e.target.value==='320'?'640px':'720px'};$('#font').onchange=e=>{$('#phone').style.setProperty('--font',e.target.value);$('#phone').dataset.large=Number(e.target.value)>1.3};$('#motion').onchange=e=>$('#phone').classList.toggle('reduced',e.target.checked);$('#components').onclick=()=>navigate('components');$('#scenario').onchange=e=>{scenario=e.target.value;applyScenario();model.busy=/保存中|处理中/.test(scenario);model.formError='';model.codeError='';render()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!model.busy){back();return}if(e.key==='Tab'){const modal=$('[role=dialog]');if(!modal)return;const list=[...modal.querySelectorAll('button,input,select')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}});
window.reviewAPI={open:id=>navigate(id),setScenario:value=>{scenario=value;applyScenario();model.busy=/保存中|处理中/.test(value);render()},catalog};
render();
